// Detailed Sale Card Component
const SaleDetailCard = ({ sale, onActionClick }) => {
  const mainItem = sale.items[0];
  const isKit = sale.items.length > 1 || mainItem?.category === 'KIT';
  const isGrouped = mainItem?.category === 'REPUESTO_AGRUPADO';

  const getStatusColor = (status) => {
    switch (status) {
      case 'para_preparar': return 'warning';
      case 'etiqueta_impresa': return 'info';
      case 'para_entregar': return 'primary';
      case 'en_camino': return 'secondary';
      case 'entregada': return 'success';
      case 'facturada': return 'success';
      case 'controlada': return 'info';
      case 'lista_para_enviar': return 'primary';
      default: return 'default';
    }
  };

  const getStatusText = (status) => {
    switch (status) {
      case 'para_preparar': return 'Para Preparar';
      case 'etiqueta_impresa': return 'Etiqueta Impresa';
      case 'para_entregar': return 'Para Entregar';
      case 'en_camino': return 'En Camino';
      case 'entregada': return 'Entregada';
      case 'facturada': return 'Facturada';
      case 'controlada': return 'Controlada';
      case 'lista_para_enviar': return 'Lista para Enviar';
      default: return status;
    }
  };

  const getShippingTypeColor = (type) => {
    switch (type) {
      case 'Flex': return 'primary';
      case 'Colecta': return 'secondary';
      case 'Turbo': return 'error';
      case 'Full': return 'success';
      case 'A convenir': return 'warning';
      default: return 'default';
    }
  };

  const getProcessChecklist = (status) => {
    const allSteps = [
      { id: 'received', label: 'Venta Recibida', icon: '📥' },
      { id: 'prepared', label: 'Paquete Preparado', icon: '📦' },
      { id: 'labeled', label: 'Etiqueta Impresa', icon: '🏷️' },
      { id: 'controlled', label: 'Control de Calidad', icon: '✅' },
      { id: 'ready', label: 'Listo para Envío', icon: '🚀' },
      { id: 'invoiced', label: 'Facturado', icon: '🧾' },
      { id: 'delivered', label: 'Entregado', icon: '🎯' }
    ];

    const completedMap = {
      'para_preparar': ['received'],
      'etiqueta_impresa': ['received', 'prepared'],
      'controlada': ['received', 'prepared', 'labeled'],
      'lista_para_enviar': ['received', 'prepared', 'labeled', 'controlled'],
      'facturada': ['received', 'prepared', 'labeled', 'controlled', 'ready'],
      'entregada': ['received', 'prepared', 'labeled', 'controlled', 'ready', 'invoiced']
    };

    const completed = completedMap[status] || [];
    return allSteps.map(step => ({
      ...step,
      completed: completed.includes(step.id),
      current: step.id === getNextStep(status)
    }));
  };

  const getNextStep = (status) => {
    const nextMap = {
      'para_preparar': 'prepared',
      'etiqueta_impresa': 'labeled',
      'controlada': 'controlled',
      'lista_para_enviar': 'ready',
      'facturada': 'invoiced',
      'entregada': 'delivered'
    };
    return nextMap[status];
  };

  const getPrimaryAction = (status) => {
    switch (status) {
      case 'para_preparar': return { label: 'Imprimir Etiqueta', icon: <Print />, color: 'primary' };
      case 'etiqueta_impresa': return { label: 'Controlar Venta', icon: <CheckBox />, color: 'warning' };
      case 'controlada': return { label: 'Marcar Listo', icon: <CheckCircle />, color: 'success' };
      case 'lista_para_enviar': return { label: 'Facturar', icon: <Receipt />, color: 'primary' };
      case 'facturada': return { label: 'Marcar Entregado', icon: <LocalShipping />, color: 'success' };
      default: return { label: 'Ver Detalle', icon: <Visibility />, color: 'default' };
    }
  };

  const checklist = getProcessChecklist(sale.logisticsStatus);
  const primaryAction = getPrimaryAction(sale.logisticsStatus);

  return (
    <Paper 
      elevation={2} 
      sx={{ 
        p: 3, 
        borderRadius: 2,
        border: '1px solid #e0e0e0',
        '&:hover': {
          boxShadow: 4,
          borderColor: 'primary.main'
        },
        transition: 'all 0.2s ease'
      }}
    >
      {/* Header Section */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 2 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
          <Avatar
            src={mainItem?.imageUrl}
            sx={{ width: 60, height: 60 }}
            variant="rounded"
          >
            📦
          </Avatar>
          <Box>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
              <Typography variant="h6" fontWeight="bold" color="primary">
                {sale.saleNumber}
              </Typography>
              <Chip 
                label={sale.store} 
                size="small" 
                color="default" 
                variant="outlined"
                sx={{ fontSize: '0.7rem' }}
              />
              {isKit && (
                <Chip label="KIT" size="small" color="warning" variant="outlined" sx={{ fontSize: '0.7rem' }} />
              )}
              {isGrouped && (
                <Chip label="AGRUPADO" size="small" color="info" variant="outlined" sx={{ fontSize: '0.7rem' }} />
              )}
            </Box>
            <Typography variant="body1" fontWeight="bold" sx={{ mb: 0.5 }}>
              {sale.title}
            </Typography>
            <Typography variant="body2" color="text.secondary">
              {sale.mla} • {sale.sku} • {mainItem?.brand || 'Sin marca'}
            </Typography>
          </Box>
        </Box>
        
        <Box sx={{ textAlign: 'right' }}>
          <Typography variant="h5" fontWeight="bold" color="success.main" sx={{ mb: 1 }}>
            ${sale.total.toLocaleString('es-AR')}
          </Typography>
          <Chip
            label={getStatusText(sale.logisticsStatus)}
            color={getStatusColor(sale.logisticsStatus)}
            sx={{ fontWeight: 'bold' }}
          />
        </Box>
      </Box>

      {/* Customer and Shipping Info */}
      <Box sx={{ display: 'flex', gap: 4, mb: 3, p: 2, backgroundColor: '#f8f9fa', borderRadius: 1 }}>
        <Box sx={{ flex: 1 }}>
          <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 0.5 }}>
            👤 Cliente
          </Typography>
          <Typography variant="body2" fontWeight="bold">
            {sale.customer.name}
          </Typography>
          <Typography variant="caption" color="text.secondary">
            📍 {sale.customer.address}
          </Typography>
        </Box>
        <Box sx={{ flex: 1 }}>
          <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 0.5 }}>
            🚚 Envío
          </Typography>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
            <Chip
              label={sale.shippingType}
              color={getShippingTypeColor(sale.shippingType)}
              size="small"
              variant="outlined"
            />
          </Box>
          <Typography variant="caption" color="text.secondary">
            {sale.shippingNumber}
          </Typography>
        </Box>
      </Box>

      {/* Items Detail for Kits */}
      {sale.items.length > 1 && (
        <Box sx={{ mb: 3, p: 2, backgroundColor: '#fff3e0', borderRadius: 1, border: '1px solid #ffcc02' }}>
          <Typography variant="subtitle2" sx={{ mb: 1, color: '#f57c00', fontWeight: 'bold' }}>
            📋 Componentes del Kit ({sale.items.length} items)
          </Typography>
          <Grid container spacing={1}>
            {sale.items.map((item, idx) => (
              <Grid item xs={12} sm={6} md={4} key={idx}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                  <Avatar src={item.imageUrl} sx={{ width: 24, height: 24 }} variant="rounded">
                    📦
                  </Avatar>
                  <Box sx={{ flex: 1 }}>
                    <Typography variant="caption" sx={{ fontWeight: 'bold', display: 'block' }}>
                      {item.title}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                      {item.brand || 'Sin marca'} • Qty: {item.quantity}
                    </Typography>
                  </Box>
                </Box>
              </Grid>
            ))}
          </Grid>
        </Box>
      )}

      {/* Process Checklist */}
      <Box sx={{ mb: 3 }}>
        <Typography variant="subtitle2" sx={{ mb: 2, fontWeight: 'bold', color: 'text.primary' }}>
          📋 Estado del Proceso
        </Typography>
        <Grid container spacing={1}>
          {checklist.map((step, idx) => (
            <Grid item xs={12} sm={6} md={3} key={step.id}>
              <Box
                sx={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 1,
                  p: 1.5,
                  borderRadius: 1,
                  backgroundColor: step.completed ? '#e8f5e8' : step.current ? '#fff3e0' : '#f5f5f5',
                  border: step.current ? '2px solid #ff9800' : '1px solid transparent',
                  transition: 'all 0.2s ease'
                }}
              >
                <Box
                  sx={{
                    width: 24,
                    height: 24,
                    borderRadius: '50%',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    backgroundColor: step.completed ? '#4caf50' : step.current ? '#ff9800' : '#ccc',
                    color: 'white',
                    fontSize: '12px'
                  }}
                >
                  {step.completed ? '✓' : step.current ? '⏳' : idx + 1}
                </Box>
                <Box>
                  <Typography 
                    variant="caption" 
                    sx={{ 
                      fontWeight: step.current ? 'bold' : 'normal',
                      color: step.completed ? 'success.main' : step.current ? 'warning.main' : 'text.secondary'
                    }}
                  >
                    {step.icon} {step.label}
                  </Typography>
                </Box>
              </Box>
            </Grid>
          ))}
        </Grid>
      </Box>

      {/* Action Buttons */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <Box sx={{ display: 'flex', gap: 1 }}>
          <Button
            variant="contained"
            color={primaryAction.color}
            startIcon={primaryAction.icon}
            onClick={() => console.log(primaryAction.label, sale.id)}
            sx={{ fontWeight: 'bold' }}
          >
            {primaryAction.label}
          </Button>
          
          {sale.logisticsStatus === 'para_preparar' && (
            <Button
              variant="outlined"
              color="secondary"
              startIcon={<Inventory />}
              onClick={() => console.log('Armar Paquete', sale.id)}
            >
              Armar Paquete
            </Button>
          )}
        </Box>

        <Box sx={{ display: 'flex', gap: 0.5 }}>
          <IconButton
            size="small"
            onClick={(e) => onActionClick(e, sale)}
            sx={{ color: 'text.secondary' }}
          >
            <MoreVert />
          </IconButton>
          <IconButton
            size="small"
            onClick={() => console.log('Ver Detalle', sale.id)}
            sx={{ color: 'text.secondary' }}
          >
            <Visibility />
          </IconButton>
          <IconButton
            size="small"
            onClick={() => console.log('Agregar Nota', sale.id)}
            sx={{ color: 'text.secondary' }}
          >
            <Note />
          </IconButton>
        </Box>
      </Box>
    </Paper>
  );
};

const VentasUnificadas = () => {
  const { sales, updateSaleStatus } = useMercadoLibreContext();
  const [filters, setFilters] = useState({
    logisticsStatus: [],
    shippingType: [],
    saleStatus: [],
    searchText: '',
    dateFrom: '',
    dateTo: '',
    stores: ['MercadoLibre', 'TiendaNube', 'Local'] // All stores selected by default
  });
  const [cascadingFilters, setCascadingFilters] = useState({});
  const [anchorEl, setAnchorEl] = useState(null);
  const [selectedSale, setSelectedSale] = useState(null);
  const [showAdvancedFilters, setShowAdvancedFilters] = useState(false);

  const handleFilterChange = (field, value) => {
    setFilters(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleCascadingFiltersChange = (newCascadingFilters) => {
    setCascadingFilters(newCascadingFilters);
  };

  const handleActionClick = (event, sale) => {
    setAnchorEl(event.currentTarget);
    setSelectedSale(sale);
  };

  const handleActionClose = () => {
    setAnchorEl(null);
    setSelectedSale(null);
  };

  const handleStatusUpdate = (saleId, newStatus) => {
    updateSaleStatus(saleId, newStatus);
  };

  // Map cascading filters to sale properties
  const mapCascadingFiltersToSale = (sale, cascadingFilters) => {
    // Map nivel1 (Estado Principal) to sale status
    if (cascadingFilters.nivel1?.length > 0) {
      const saleStateMap = {
        'para_preparar': 'A_ENVIAR',
        'etiqueta_impresa': 'A_ENVIAR',
        'controlada': 'A_ENVIAR',
        'lista_para_enviar': 'A_ENVIAR',
        'facturada': 'ENVIADO',
        'en_camino': 'ENVIADO',
        'entregada': 'ENTREGADO'
      };
      const mappedState = saleStateMap[sale.logisticsStatus];
      if (!cascadingFilters.nivel1.includes(mappedState)) return false;
    }

    // Map nivel2 (Tipo de Envío) to shipping type
    if (cascadingFilters.nivel2?.length > 0) {
      const shippingTypeMap = {
        'Flex': 'FLEX',
        'Colecta': 'COLECTA',
        'Turbo': 'TURBO',
        'Full': 'FULL',
        'A convenir': 'A_COORDINAR'
      };
      const mappedShipping = shippingTypeMap[sale.shippingType];
      if (!cascadingFilters.nivel2.includes(mappedShipping)) return false;
    }

    // For now, other levels (3-8) are not mapped to existing sale data
    // They would be used when we have more detailed logistics tracking

    return true;
  };

  // Filter sales based on current filters and cascading filters
  const filteredSales = useMemo(() => {
    return sales.filter(sale => {
      // Apply traditional filters
      if (filters.logisticsStatus.length > 0 && !filters.logisticsStatus.includes(sale.logisticsStatus)) return false;
      if (filters.shippingType.length > 0 && !filters.shippingType.includes(sale.shippingType)) return false;
      if (filters.saleStatus.length > 0 && !filters.saleStatus.includes(sale.status)) return false;
      if (filters.searchText) {
        const searchLower = filters.searchText.toLowerCase();
        const matchesSearch = (
          sale.mla?.toLowerCase().includes(searchLower) ||
          sale.sku?.toLowerCase().includes(searchLower) ||
          sale.title?.toLowerCase().includes(searchLower) ||
          sale.customer?.name?.toLowerCase().includes(searchLower) ||
          sale.shippingNumber?.toLowerCase().includes(searchLower) ||
          sale.saleNumber?.toLowerCase().includes(searchLower)
        );
        if (!matchesSearch) return false;
      }

      // Apply date filters
      if (filters.dateFrom || filters.dateTo) {
        const saleDate = new Date(sale.date);
        if (filters.dateFrom && saleDate < new Date(filters.dateFrom)) return false;
        if (filters.dateTo && saleDate > new Date(filters.dateTo + 'T23:59:59')) return false;
      }

      // Apply store filter
      if (filters.stores.length > 0 && !filters.stores.includes(sale.store)) return false;

      // Apply cascading filters
      if (Object.values(cascadingFilters).some(level => level.length > 0)) {
        return mapCascadingFiltersToSale(sale, cascadingFilters);
      }

      return true;
    });
  }, [sales, filters, cascadingFilters]);

  // Calculate stats
  const stats = useMemo(() => {
    const total = filteredSales.length;
    const byLogisticsStatus = {};
    const byShippingType = {};
    const bySaleStatus = {};

    filteredSales.forEach(sale => {
      byLogisticsStatus[sale.logisticsStatus] = (byLogisticsStatus[sale.logisticsStatus] || 0) + 1;
      byShippingType[sale.shippingType] = (byShippingType[sale.shippingType] || 0) + 1;
      bySaleStatus[sale.status] = (bySaleStatus[sale.status] || 0) + 1;
    });

    return { total, byLogisticsStatus, byShippingType, bySaleStatus };
  }, [filteredSales]);

  const getStatusColor = (status) => {
    switch (status) {
      case 'para_preparar': return 'warning';
      case 'etiqueta_impresa': return 'info';
      case 'para_entregar': return 'primary';
      case 'en_camino': return 'secondary';
      case 'entregada': return 'success';
      case 'facturada': return 'success';
      case 'controlada': return 'info';
      case 'lista_para_enviar': return 'primary';
      default: return 'default';
    }
  };

  const getShippingTypeColor = (type) => {
    switch (type) {
      case 'Flex': return 'primary';
      case 'Colecta': return 'secondary';
      case 'Turbo': return 'error';
      case 'Full': return 'success';
      case 'A convenir': return 'warning';
      default: return 'default';
    }
  };

  const getStatusText = (status) => {
    switch (status) {
      case 'para_preparar': return 'Para Preparar';
      case 'etiqueta_impresa': return 'Etiqueta Impresa';
      case 'para_entregar': return 'Para Entregar';
      case 'en_camino': return 'En Camino';
      case 'entregada': return 'Entregada';
      case 'facturada': return 'Facturada';
      case 'controlada': return 'Controlada';
      case 'lista_para_enviar': return 'Lista para Enviar';
      default: return status;
    }
  };

  const getStatusProgress = (status) => {
    const statusOrder = ['para_preparar', 'etiqueta_impresa', 'controlada', 'lista_para_enviar', 'facturada', 'entregada'];
    const currentIndex = statusOrder.indexOf(status);
    return ((currentIndex + 1) / statusOrder.length) * 100;
  };

  const getNextActions = (status) => {
    switch (status) {
      case 'para_preparar': return ['Imprimir Etiqueta', 'Armar Paquete'];
      case 'etiqueta_impresa': return ['Mensajería', 'Controlar'];
      case 'controlada': return ['Lista para Enviar', 'Generar Remito'];
      case 'lista_para_enviar': return ['Facturar', 'Enviar'];
      case 'facturada': return ['Marcar Entregada'];
      case 'entregada': return ['Ver Factura'];
      default: return [];
    }
  };

  const getCompletedSteps = (status) => {
    const allSteps = ['Preparar', 'Etiquetar', 'Controlar', 'Listar', 'Facturar', 'Entregar'];
    const statusMap = {
      'para_preparar': [],
      'etiqueta_impresa': ['Preparar'],
      'controlada': ['Preparar', 'Etiquetar'],
      'lista_para_enviar': ['Preparar', 'Etiquetar', 'Controlar'],
      'facturada': ['Preparar', 'Etiquetar', 'Controlar', 'Listar'],
      'entregada': ['Preparar', 'Etiquetar', 'Controlar', 'Listar', 'Facturar']
    };
    return statusMap[status] || [];
  };

  const columns = [
    {
      field: 'saleInfo',
      headerName: 'Información de Venta',
      width: 400,
      renderCell: (params) => {
        const sale = params.row;
        const mainItem = sale.items[0];
        const isKit = sale.items.length > 1 || mainItem?.category === 'KIT';
        const isGrouped = mainItem?.category === 'REPUESTO_AGRUPADO';
        
        return (
          <Box sx={{ py: 1 }}>
            {/* Header Row */}
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
              <Avatar
                src={mainItem?.imageUrl}
                sx={{ width: 40, height: 40 }}
                variant="rounded"
              >
                📦
              </Avatar>
              <Box sx={{ flex: 1 }}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                  <Typography variant="body2" fontWeight="bold" color="primary">
                    {sale.saleNumber}
                  </Typography>
                  {isKit && (
                    <Chip label="KIT" size="small" color="warning" variant="outlined" sx={{ height: 20, fontSize: '0.65rem' }} />
                  )}
                  {isGrouped && (
                    <Chip label="AGRUPADO" size="small" color="info" variant="outlined" sx={{ height: 20, fontSize: '0.65rem' }} />
                  )}
                </Box>
                <Typography variant="body2" fontWeight="bold">
                  {sale.title}
                </Typography>
                <Typography variant="caption" color="text.secondary">
                  {sale.mla} • {sale.sku} • {mainItem?.brand || 'Sin marca'}
                </Typography>
              </Box>
            </Box>
            
            {/* Items Detail */}
            {sale.items.length > 1 && (
              <Box sx={{ ml: 5, mb: 1 }}>
                <Typography variant="caption" color="text.secondary" sx={{ fontWeight: 'bold' }}>
                  Componentes ({sale.items.length}):
                </Typography>
                {sale.items.slice(0, 3).map((item, idx) => (
                  <Typography key={idx} variant="caption" color="text.secondary" sx={{ display: 'block', ml: 1 }}>
                    • {item.title} ({item.quantity}x) - {item.brand || 'Sin marca'}
                  </Typography>
                ))}
                {sale.items.length > 3 && (
                  <Typography variant="caption" color="text.secondary" sx={{ ml: 1, fontStyle: 'italic' }}>
                    ... y {sale.items.length - 3} más
                  </Typography>
                )}
              </Box>
            )}
          </Box>
        );
      }
    },
    {
      field: 'customerShipping',
      headerName: 'Cliente y Envío',
      width: 200,
      renderCell: (params) => {
        const sale = params.row;
        return (
          <Box sx={{ py: 1 }}>
            <Typography variant="body2" fontWeight="bold">
              {sale.customer.name}
            </Typography>
            <Typography variant="caption" color="text.secondary" sx={{ display: 'block' }}>
              📍 {sale.customer.address?.split(',')[0] || 'Sin dirección'}
            </Typography>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, mt: 0.5 }}>
              <Chip
                label={sale.shippingType}
                color={getShippingTypeColor(sale.shippingType)}
                size="small"
                variant="outlined"
                sx={{ height: 20, fontSize: '0.65rem' }}
              />
            </Box>
            <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.5 }}>
              🚚 {sale.shippingNumber}
            </Typography>
          </Box>
        );
      }
    },
    {
      field: 'processStatus',
      headerName: 'Estado y Progreso',
      width: 250,
      renderCell: (params) => {
        const sale = params.row;
        const nextActions = getNextActions(sale.logisticsStatus);
        const completedSteps = getCompletedSteps(sale.logisticsStatus);
        
        return (
          <Box sx={{ py: 1, width: '100%' }}>
            {/* Current Status */}
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
              <Chip
                label={getStatusText(sale.logisticsStatus)}
                color={getStatusColor(sale.logisticsStatus)}
                size="small"
                sx={{ fontWeight: 'bold' }}
              />
              <Typography variant="caption" color="text.secondary">
                ${sale.total.toLocaleString('es-AR')}
              </Typography>
            </Box>
            
            {/* Progress Bar */}
            <Box
              sx={{
                width: '100%',
                height: 6,
                backgroundColor: '#e0e0e0',
                borderRadius: 3,
                overflow: 'hidden',
                mb: 1
              }}
            >
              <Box
                sx={{
                  width: `${getStatusProgress(sale.logisticsStatus)}%`,
                  height: '100%',
                  backgroundColor: theme => theme.palette[getStatusColor(sale.logisticsStatus)]?.main || '#1976d2',
                  transition: 'width 0.3s ease'
                }}
              />
            </Box>
            
            {/* Completed Steps */}
            <Typography variant="caption" color="success.main" sx={{ display: 'block', mb: 0.5 }}>
              ✅ Completado: {completedSteps.join(', ')}
            </Typography>
            
            {/* Next Actions */}
            {nextActions.length > 0 && (
              <Typography variant="caption" color="warning.main" sx={{ display: 'block' }}>
                ⏳ Pendiente: {nextActions.slice(0, 2).join(', ')}
              </Typography>
            )}
          </Box>
        );
      }
    },
    {
      field: 'quickActions',
      headerName: 'Acciones Rápidas',
      width: 200,
      renderCell: (params) => {
        const sale = params.row;
        const status = sale.logisticsStatus;
        
        return (
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, py: 1 }}>
            {/* Primary Quick Actions */}
            <Box sx={{ display: 'flex', gap: 0.5 }}>
              {status === 'para_preparar' && (
                <>
                  <Button
                    size="small"
                    variant="contained"
                    color="primary"
                    startIcon={<Print />}
                    onClick={() => console.log('Imprimir Etiqueta', sale.id)}
                    sx={{ fontSize: '0.7rem', minWidth: 'auto', px: 1 }}
                  >
                    Etiqueta
                  </Button>
                  <Button
                    size="small"
                    variant="outlined"
                    color="secondary"
                    startIcon={<Inventory />}
                    onClick={() => console.log('Armar Paquete', sale.id)}
                    sx={{ fontSize: '0.7rem', minWidth: 'auto', px: 1 }}
                  >
                    Armar
                  </Button>
                </>
              )}
              
              {status === 'etiqueta_impresa' && (
                <>
                  <Button
                    size="small"
                    variant="contained"
                    color="warning"
                    startIcon={<CheckBox />}
                    onClick={() => console.log('Controlar Venta', sale.id)}
                    sx={{ fontSize: '0.7rem', minWidth: 'auto', px: 1 }}
                  >
                    Controlar
                  </Button>
                  <Button
                    size="small"
                    variant="outlined"
                    color="primary"
                    startIcon={<LocalShipping />}
                    onClick={() => console.log('Mensajería', sale.id)}
                    sx={{ fontSize: '0.7rem', minWidth: 'auto', px: 1 }}
                  >
                    Enviar
                  </Button>
                </>
              )}
              
              {(status === 'controlada' || status === 'lista_para_enviar') && (
                <>
                  <Button
                    size="small"
                    variant="contained"
                    color="success"
                    startIcon={<Receipt />}
                    onClick={() => console.log('Facturar', sale.id)}
                    sx={{ fontSize: '0.7rem', minWidth: 'auto', px: 1 }}
                  >
                    Facturar
                  </Button>
                  <Button
                    size="small"
                    variant="outlined"
                    color="primary"
                    startIcon={<Send />}
                    onClick={() => console.log('Enviar', sale.id)}
                    sx={{ fontSize: '0.7rem', minWidth: 'auto', px: 1 }}
                  >
                    Enviar
                  </Button>
                </>
              )}
            </Box>
            
            {/* Secondary Actions */}
            <Box sx={{ display: 'flex', gap: 0.5 }}>
              <IconButton
                size="small"
                onClick={(e) => handleActionClick(e, sale)}
                sx={{ minWidth: 'auto' }}
              >
                <MoreVert fontSize="small" />
              </IconButton>
              <IconButton
                size="small"
                onClick={() => console.log('Ver Detalle', sale.id)}
                sx={{ minWidth: 'auto' }}
              >
                <Visibility fontSize="small" />
              </IconButton>
              <IconButton
                size="small"
                onClick={() => console.log('Agregar Nota', sale.id)}
                sx={{ minWidth: 'auto' }}
              >
                <Note fontSize="small" />
              </IconButton>
            </Box>
          </Box>
        );
      }
    }
  ];

  return (
    <Box>
      {/* Store Filter - Primary */}
      <Paper sx={{ p: 2, mb: 2, border: '2px solid', borderColor: 'primary.main', borderRadius: 2 }}>
        <Typography variant="h6" gutterBottom sx={{ display: 'flex', alignItems: 'center', gap: 1, color: 'primary.main' }}>
          <Dashboard />
          Tiendas a Gestionar
        </Typography>
        <Grid container spacing={1}>
          {['MercadoLibre', 'TiendaNube', 'Local'].map((store) => (
            <Grid item key={store}>
              <Chip
                label={`${store} (${sales.filter(s => s.store === store).length})`}
                onClick={() => {
                  const newStores = filters.stores.includes(store)
                    ? filters.stores.filter(s => s !== store)
                    : [...filters.stores, store];
                  handleFilterChange('stores', newStores);
                }}
                color={filters.stores.includes(store) ? 'primary' : 'default'}
                variant={filters.stores.includes(store) ? 'filled' : 'outlined'}
                sx={{
                  cursor: 'pointer',
                  '&:hover': {
                    backgroundColor: filters.stores.includes(store) ? '#1565c0' : 'grey.100'
                  }
                }}
              />
            </Grid>
          ))}
          <Grid item>
            <Button
              size="small"
              variant="text"
              onClick={() => handleFilterChange('stores', ['MercadoLibre', 'TiendaNube', 'Local'])}
              sx={{ ml: 1 }}
            >
              Todas
            </Button>
          </Grid>
        </Grid>
      </Paper>

      {/* Primary Cascading Filters - Always Visible */}
      <Paper sx={{ p: 1.5, mb: 2 }}>
        <CascadingFilters 
          onFiltersChange={handleCascadingFiltersChange}
          initialFilters={cascadingFilters}
          salesData={sales.filter(sale => filters.stores.includes(sale.store))}
        />
      </Paper>

      {/* Quick Search and Advanced Filters Toggle */}
      <Paper sx={{ p: 2, mb: 2 }}>
        <Grid container spacing={2} alignItems="center">
          <Grid item xs={12} md={6}>
            <TextField
              fullWidth
              label="Búsqueda Rápida"
              value={filters.searchText}
              onChange={(e) => handleFilterChange('searchText', e.target.value)}
              placeholder="N° Venta, MLA, SKU, Cliente..."
              size="small"
            />
          </Grid>
          <Grid item xs={12} md={3}>
            <Button
              fullWidth
              variant="outlined"
              startIcon={<FilterList />}
              endIcon={showAdvancedFilters ? <ExpandLess /> : <ExpandMore />}
              onClick={() => setShowAdvancedFilters(!showAdvancedFilters)}
              sx={{ height: '40px' }}
            >
              Filtros Adicionales
            </Button>
          </Grid>
          <Grid item xs={12} md={3}>
            <Typography variant="body2" color="text.secondary" sx={{ textAlign: 'center' }}>
              <strong>{filteredSales.length}</strong> ventas encontradas
            </Typography>
          </Grid>
        </Grid>
      </Paper>

      {/* Collapsible Additional Filters */}
      <Collapse in={showAdvancedFilters}>
        <Paper sx={{ p: 2, mb: 2 }}>
          <Typography variant="subtitle1" gutterBottom sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <FilterList />
            Filtros Adicionales
          </Typography>
          <Grid container spacing={2}>
            <Grid item xs={12} md={2.4}>
              <TextField
                fullWidth
                label="Desde"
                type="date"
                value={filters.dateFrom}
                onChange={(e) => handleFilterChange('dateFrom', e.target.value)}
                InputLabelProps={{ shrink: true }}
                size="small"
              />
            </Grid>
            <Grid item xs={12} md={2.4}>
              <TextField
                fullWidth
                label="Hasta"
                type="date"
                value={filters.dateTo}
                onChange={(e) => handleFilterChange('dateTo', e.target.value)}
                InputLabelProps={{ shrink: true }}
                size="small"
              />
            </Grid>
            <Grid item xs={12} md={2.4}>
              <FormControl fullWidth size="small">
                <InputLabel>Estado Logística</InputLabel>
                <Select
                  multiple
                  value={filters.logisticsStatus}
                  onChange={(e) => handleFilterChange('logisticsStatus', e.target.value)}
                  label="Estado Logística"
                  renderValue={(selected) => (
                    <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                      {selected.map((value) => (
                        <Chip key={value} label={getStatusText(value)} size="small" />
                      ))}
                    </Box>
                  )}
                >
                  <MenuItem value="para_preparar">Para Preparar</MenuItem>
                  <MenuItem value="etiqueta_impresa">Etiqueta Impresa</MenuItem>
                  <MenuItem value="controlada">Controlada</MenuItem>
                  <MenuItem value="lista_para_enviar">Lista para Enviar</MenuItem>
                  <MenuItem value="facturada">Facturada</MenuItem>
                  <MenuItem value="entregada">Entregada</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={2.4}>
              <FormControl fullWidth size="small">
                <InputLabel>Tipo de Envío</InputLabel>
                <Select
                  multiple
                  value={filters.shippingType}
                  onChange={(e) => handleFilterChange('shippingType', e.target.value)}
                  label="Tipo de Envío"
                  renderValue={(selected) => (
                    <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                      {selected.map((value) => (
                        <Chip key={value} label={value} size="small" />
                      ))}
                    </Box>
                  )}
                >
                  <MenuItem value="Flex">Flex</MenuItem>
                  <MenuItem value="Colecta">Colecta</MenuItem>
                  <MenuItem value="Turbo">Turbo</MenuItem>
                  <MenuItem value="Full">Full</MenuItem>
                  <MenuItem value="A convenir">A convenir</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={2.4}>
              <Button
                fullWidth
                variant="outlined"
                color="error"
                onClick={() => {
                  setFilters({ logisticsStatus: [], shippingType: [], saleStatus: [], searchText: '', dateFrom: '', dateTo: '', stores: ['MercadoLibre', 'TiendaNube', 'Local'] });
                  setCascadingFilters({});
                }}
                size="small"
              >
                Limpiar Todo
              </Button>
            </Grid>
          </Grid>
        </Paper>
      </Collapse>

      {/* Results */}
      {filteredSales.length === 0 ? (
        <Alert severity="info">
          No se encontraron ventas con los filtros aplicados.
        </Alert>
      ) : (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
          {filteredSales.map((sale) => (
            <SaleDetailCard key={sale.id} sale={sale} onActionClick={handleActionClick} />
          ))}
        </Box>
      )}

      {/* Action Menu */}
      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleActionClose}
      >
        <MenuItem onClick={() => { console.log('Imprimir Etiqueta', selectedSale); handleActionClose(); }}>
          <Print sx={{ mr: 1 }} /> Imprimir Etiqueta
        </MenuItem>
        <MenuItem onClick={() => { console.log('Mensajería', selectedSale); handleActionClose(); }}>
          <LocalShipping sx={{ mr: 1 }} /> Mensajería
        </MenuItem>
        <MenuItem onClick={() => { console.log('Armar Paquete', selectedSale); handleActionClose(); }}>
          <Inventory sx={{ mr: 1 }} /> Armar Paquete
        </MenuItem>
        <Divider />
        <MenuItem onClick={() => { console.log('Ver Detalle', selectedSale); handleActionClose(); }}>
          <Visibility sx={{ mr: 1 }} /> Ver Detalle
        </MenuItem>
        <MenuItem onClick={() => { console.log('Agregar Nota', selectedSale); handleActionClose(); }}>
          <Note sx={{ mr: 1 }} /> Agregar Nota
        </MenuItem>
        <MenuItem onClick={() => { console.log('Generar Remito', selectedSale); handleActionClose(); }}>
          <Receipt sx={{ mr: 1 }} /> Generar Remito
        </MenuItem>
      </Menu>
    </Box>
  );
};

export default VentasUnificadas;
